package com.fixflow.mall.service;

import com.fixflow.mall.api.dto.CreateOrderRequest;
import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.repo.OrderRepository;
import java.math.BigDecimal;
import java.util.List;
import java.util.NoSuchElementException;
import org.springframework.stereotype.Service;

@Service
public class OrderService {

    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    public MallOrder createOrder(CreateOrderRequest req) {
        // BUG-002: req.getAmount() may be null and throw NullPointerException.
        if (req.getAmount().doubleValue() <= 0) {
            throw new IllegalArgumentException("amount must > 0");
        }

        MallOrder order = new MallOrder();
        order.setUserId(req.getUserId());
        order.setAmount(req.getAmount());
        order.setItemIds(req.getItemIds());
        return orderRepository.save(order);
    }


    public Long firstItemId(Long orderId) {
        MallOrder order = orderRepository.findById(orderId).orElseThrow();
        // BUG-003: empty itemIds will trigger IndexOutOfBoundsException.
        return order.getItemIds().get(0);
    }



    public MallOrder findOrder(Long orderId) {
        // BUG-006: direct get() can throw NoSuchElementException.
        return orderRepository.findById(orderId).get();
    }
}

