package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.repo.OrderRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Collections;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    private static final Long ORDER_ID = 1L;
    private MallOrder mockOrder;

    @BeforeEach
    void setUp() {
        mockOrder = mock(MallOrder.class);
    }

    @Test
    @DisplayName("正向测试: firstItemId 返回列表中的第一个元素")
    void firstItemId_WithNonEmptyItemIds_ShouldReturnFirstItemId() {
        // Arrange
        List<Long> itemIds = List.of(100L, 200L, 300L);
        when(orderRepository.findById(ORDER_ID)).thenReturn(Optional.of(mockOrder));
        when(mockOrder.getItemIds()).thenReturn(itemIds);

        // Act
        Long result = orderService.firstItemId(ORDER_ID);

        // Assert
        assertEquals(100L, result);
        verify(orderRepository).findById(ORDER_ID);
        verify(mockOrder).getItemIds();
    }

    @Test
    @DisplayName("边界测试: firstItemId 在 itemIds 为空列表时返回 null")
    void firstItemId_WithEmptyItemIds_ShouldReturnNull() {
        // Arrange
        when(orderRepository.findById(ORDER_ID)).thenReturn(Optional.of(mockOrder));
        when(mockOrder.getItemIds()).thenReturn(Collections.emptyList());

        // Act
        Long result = orderService.firstItemId(ORDER_ID);

        // Assert
        assertNull(result);
        verify(orderRepository).findById(ORDER_ID);
        verify(mockOrder).getItemIds();
    }

    @Test
    @DisplayName("空值/null 处理: firstItemId 在 itemIds 为 null 时返回 null")
    void firstItemId_WithNullItemIds_ShouldReturnNull() {
        // Arrange
        when(orderRepository.findById(ORDER_ID)).thenReturn(Optional.of(mockOrder));
        when(mockOrder.getItemIds()).thenReturn(null);

        // Act
        Long result = orderService.firstItemId(ORDER_ID);

        // Assert
        assertNull(result);
        verify(orderRepository).findById(ORDER_ID);
        verify(mockOrder).getItemIds();
    }

    @Test
    @DisplayName("异常测试: firstItemId 在订单不存在时抛出 NoSuchElementException")
    void firstItemId_WithNonExistentOrderId_ShouldThrowNoSuchElementException() {
        // Arrange
        when(orderRepository.findById(ORDER_ID)).thenReturn(Optional.empty());

        // Act & Assert
        assertThrows(NoSuchElementException.class, () -> orderService.firstItemId(ORDER_ID));
        verify(orderRepository).findById(ORDER_ID);
    }
}
